$_LANG['ssl']['approverEmailProcess'] = "<h4>核准人電子郵件驗證程序</h4><p>核發 SSL 憑證前，憑證授權單位必須驗證憑證訂單的真實性，確認申請有效且來自網域的授權擁有者。</p><p>以電子郵件驗證網域是憑證訂單最常見的驗證方式。憑證授權單位會根據網域公開的 WHOIS 資料，整理常見管理電子郵件地址（例如 admin 或 webmaster）作為可核准地址。您只能使用其中一個地址確認網域所有權。</p>";
$_LANG['ssl']['approverEmailUpdateInfo'] = "<p>您很快會收到寄至 <em>:newApproverEmail</em> 的電子郵件，請透過該郵件核准憑證。</p><p>如果沒有收到郵件，請檢查垃圾郵件篩選器及防毒軟體隔離區。如果仍找不到，請<a href=\"submitticket.php\">聯絡客服</a>。</p>";
$_LANG['ssl']['approverEmailUpdateSuccess'] = "已成功更新核准人電子郵件！";
