$_LANG['store']['emailServices']['benefits']['archiving']['a1'] = "電子郵件封存會保存並保護所有收發郵件，方便日後存取。您可以用來復原遺失或意外刪除的郵件、加快稽核回應、保護包含智慧財產的郵件及附件，並在發生訴訟時進行電子蒐證（eDiscovery）。";
$_LANG['store']['emailServices']['benefits']['archiving']['a2a'] = "找不到去年某封重要郵件，因而面臨罰款或錯失重要商機嗎？專業的電子郵件封存服務可協助您避免此類問題。電子郵件封存是安全備份所有郵件並符合法規要求的重要工具。";
$_LANG['store']['emailServices']['benefits']['archiving']['a2b'] = "電子郵件往來具有司法效力且具法律約束力，因此郵件合規已成為組織非常重要的課題。部分產業因此要求安全備份所有郵件並符合法規。";
