$_LANG['store']['emailServices']['benefits']['incoming']['3'] = "設定簡單";
$_LANG['store']['emailServices']['benefits']['incoming']['4'] = "提升收件服務的持續性與備援能力";
$_LANG['store']['emailServices']['benefits']['incoming']['5'] = "提供多種報表選項";
$_LANG['store']['emailServices']['benefits']['incoming']['6'] = "介面簡單易用，讓您完整掌控電子郵件";
$_LANG['store']['emailServices']['benefits']['incoming']['7'] = "提升員工生產力";
$_LANG['store']['emailServices']['benefits']['incoming']['8'] = "相容於任何郵件伺服器";
$_LANG['store']['emailServices']['benefits']['incoming']['a1'] = "進站郵件篩選會檢查所有收到的郵件，以近乎 100% 的準確率，在垃圾郵件及病毒進入網路前將其攔截。功能完整的控制台讓您隨時掌握郵件狀態。即使郵件伺服器停機，郵件也會暫存在佇列中；您可以透過網頁介面存取、閱讀及回覆佇列中的郵件，確保收件服務不中斷！";
$_LANG['store']['emailServices']['benefits']['incoming']['a2'] = "避免 IT 網路遭受威脅。如果收件匣每天都塞滿未經要求的大量郵件，就代表您需要專業的進站郵件篩選服務。全面保護收件匣，遠離垃圾郵件、病毒及惡意軟體威脅！";
$_LANG['store']['emailServices']['benefits']['incoming']['a3'] = "將網域（自動）設定至進站郵件篩選並啟用篩選後，郵件就會經過 SpamExperts 篩選雲端。系統會即時安全地分析及掃描收到的郵件，無須訓練或額外設定，啟用後即可使用。偵測到的垃圾郵件會移至隔離區，其他郵件則會送至您的郵件伺服器。您可以透過易用的 SpamPanel、電子郵件報表，甚至直接在郵件用戶端監控隔離區！不必再花時間處理垃圾郵件，專心投入業務，同時仍能全面掌控郵件。";
$_LANG['store']['emailServices']['benefits']['incoming']['q1'] = "為什麼選擇 SpamExperts 進站郵件篩選？";
$_LANG['store']['emailServices']['benefits']['incoming']['q2'] = "為什麼需要專業的進站郵件篩選？";
