$_LANG['store']['emailServices']['benefits']['outgoing']['2'] = "保護品牌及 IT 系統的信譽";
$_LANG['store']['emailServices']['benefits']['outgoing']['3'] = "避免因移出黑名單而產生的費用";
$_LANG['store']['emailServices']['benefits']['outgoing']['4'] = "提升出站郵件服務的持續性與寄送率";
