$_LANG['store']['emailServices']['benefits']['outgoing']['6'] = "更有效管理濫用情況";
$_LANG['store']['emailServices']['benefits']['outgoing']['a1'] = "出站郵件篩選是保護 IT 基礎架構信譽並確保郵件安全送達的重要措施。此專業服務可阻止垃圾郵件及病毒從您的網路寄出，避免 IP 位址再次遭列入黑名單。此外，SpamExperts 出站郵件篩選提供報表及工具，協助您偵測遭入侵的帳戶並停用寄送垃圾郵件的使用者。";
$_LANG['store']['emailServices']['benefits']['outgoing']['a2'] = "您的網路是否曾在您不知情的情況下寄出垃圾郵件？網路安全弱點可能讓裝置遭入侵並傳送出站 SMTP，導致垃圾郵件或惡意軟體從您的網路寄出，而您卻毫不知情！因此，採用專業的出站郵件篩選服務至關重要。維護公司信譽、防止垃圾郵件離開網路並避免 IP 遭列入黑名單，確保郵件送達正確目的地。";
