$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['4'] = "在網站加入 Facebook、Twitter、LinkedIn 與 Pinterest 等社群平台圖示，鼓勵訪客對內容按讚並分享。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['5'] = "讓訪客不必離開網站，也能在您連結的 Facebook 專頁留言與按讚。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['6'] = "每次在 Instagram 發文後，自動將相片展示於網站；也可顯示 Twitter 即時動態，讓網站訪客掌握最新消息。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['1'] = "拖放式編輯器會醒目標示可放置區域，讓客戶直接在頁面新增與排列網站功能。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['2'] = "使用文字、按鈕、相片或圖示等現成版面元件，自訂專業質感的網站配置。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['3'] = "無須花時間調整內容版面。透過 350 多種內容區塊，即使沒有技術背景也能建立專業網站。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['4'] = "網站在各種裝置上都能呈現良好效果。範本採 100% 響應式設計，適用於智慧型手機、平板電腦與桌上型電腦。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['5'] = "使用超過 200,000 張高解析度專業優質相片，豐富您的網站。Site Builder 也包含嵌入式影片與圖片最佳化功能。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['6'] = "透過即時儲存，確保工作成果不會遺失。編輯器會在您操作時自動儲存所有內容。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['1'] = "無論您經營精品店、商店或大型零售店，都有適用方案可管理 10、50 或 500 項產品。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['10'] = "立即透過電子郵件接收訂單通知。管理並總覽所有訂單、搜尋訂單、依分類篩選，還可更新訂單與客戶資訊，以及新增配送追蹤號碼。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['2'] = "連結 Paypal、Square、Stripe 及 50 多家值得信賴的信用卡付款服務商，即可立即接受信用卡付款。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['3'] = "讓客戶更快速、輕鬆地結帳，並可選擇在結帳時註冊。提供安全的單頁結帳流程，並可附上客戶的訂單備註。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['5'] = "從多種產品頁面版型中選擇，並依需求自訂說明與設計。將產品分類整理，讓客戶更容易找到所需產品。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['6'] = "建立折價券或促銷代碼以提高銷售額。並列顯示原價與折扣價，提升轉換率。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['7'] = "庫存追蹤可協助您判斷何時需要補貨，以及哪些產品款式最受歡迎。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['8'] = "將線上商店連結至 USPS、FedEx、UPS、Australia Post、Canada Post 等貨運業者，讓客戶在結帳時查看即時運費。";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['9'] = "支援任何國家的稅額計算，也可定義特定區域。您可以依地點設定稅額、依產品群組加徵稅金，或設定免稅產品，完整掌控稅額計算方式。";
$_LANG['store']['siteBuilder']['intro1'] = "建立網路形象需要合適的平台。使用我們的拖放式 DIY Site Builder，讓您更受矚目。";
$_LANG['store']['siteBuilder']['intro2'] = "無論您想宣傳自己或自家企業，我們的網站建置器都採用範本與精靈式設計，並提供引導式內容，初學者也能輕鬆上手，同時具備專業人士所需的豐富功能。使用起來就像 PowerPoint，卻更強大、優雅又簡單，是一套讓您樂於使用的解決方案。";
