$_LANG['store']['sitelock']['contentBodyParagraph1'] = "SiteLock&trade; 是全球領先的網站安全服務，保護您的網站，讓您安心無虞。";
$_LANG['store']['sitelock']['contentBodyParagraph2'] = "SiteLock 每日惡意軟體掃描會找出網站弱點及已知的惡意軟體，並自動將其從網站移除，以防護您的網站與訪客免受威脅。";
$_LANG['store']['sitelock']['contentBodyParagraph3'] = "此外，您還可使用 SiteLock 信任標章，建立客戶信心；此標章經證實能提升銷售與轉換率。";
$_LANG['store']['sitelock']['contentHeadline'] = "網站安全與惡意軟體防護";
$_LANG['store']['sitelock']['emergencyPlanAftercareContent'] = "復原後，我們會持續監控您的網站 7 天，確保網站未受惡意軟體感染。";
$_LANG['store']['sitelock']['emergencyPlanAftercareTitle'] = "7 天售後服務";
$_LANG['store']['sitelock']['emergencyPlanBody'] = "若網站遭到攻擊並被入侵，請立即取得緊急協助，迅速復原網站。SiteLock 緊急應變服務會這樣協助您：";
$_LANG['store']['sitelock']['emergencyPlanHeadline'] = "立即透過 SiteLock 緊急應變服務修復";
$_LANG['store']['sitelock']['emergencyPlanMalwareContent'] = "如果自動化技術無法移除惡意內容，我們會改以人工清理。";
$_LANG['store']['sitelock']['emergencyPlanMalwareTitle'] = "完整移除惡意軟體";
$_LANG['store']['sitelock']['emergencyPlanOnlyCost'] = "7 天防護僅需 :price";
$_LANG['store']['sitelock']['emergencyPlanPaymentContent'] = "緊急服務僅收取一次性費用，不會定期收費或要求訂閱。";
$_LANG['store']['sitelock']['emergencyPlanPaymentTitle'] = "單次付款";
$_LANG['store']['sitelock']['emergencyPlanPriorityContent'] = "使用緊急方案可優先處理，直接排入最前面的佇列。";
$_LANG['store']['sitelock']['emergencyPlanPriorityTitle'] = "優先處理";
$_LANG['store']['sitelock']['emergencyPlanResponseContent'] = "享有最快回應時間，並於 30 分鐘內開始分析及復原網站。";
$_LANG['store']['sitelock']['emergencyPlanResponseTitle'] = "立即回應";
$_LANG['store']['sitelock']['emergencyPlanTitle'] = "網站遭到入侵？";
$_LANG['store']['sitelock']['emergencyPlanUpdatesContent'] = "清理與復原網站期間，透過即時更新追蹤處理進度。";
$_LANG['store']['sitelock']['emergencyPlanUpdatesTitle'] = "即時更新";
$_LANG['store']['sitelock']['faq'] = "常見問題";
$_LANG['store']['sitelock']['faqFiveBody'] = "不會。網站掃描期間，SiteLock 會將相關檔案下載至安全伺服器，並在該處執行掃描。這不會影響網站內容、程式碼、頻寬或伺服器資源。";
$_LANG['store']['sitelock']['faqFiveTitle'] = "SiteLock 會影響網站效能嗎？";
$_LANG['store']['sitelock']['faqFourBodyParagraph1'] = ":vulnerabilityStrong 是網站或網頁應用程式程式碼中的弱點或設定錯誤，可能讓攻擊者取得一定程度的網站控制權，甚至控制主機伺服器。多數弱點會透過自動化方式遭到利用，例如弱點掃描器與殭屍網路。";
$_LANG['store']['sitelock']['faqFourBodyParagraph2'] = ":malwareStrong 是惡意軟體的簡稱，可用來蒐集敏感資料、未經授權存取網站，甚至控制電腦。";
$_LANG['store']['sitelock']['faqFourTitle'] = "什麼是弱點與惡意軟體？";
$_LANG['store']['sitelock']['faqOneBody'] = "SiteLock 為各種規模的網站提供簡單、快速且實惠的安全防護。公司成立於 2008 年，保護全球超過 12 百萬個網站。SiteLock 雲端產品組合提供自動化網站弱點偵測與惡意軟體移除、DDoS 防護、網站加速、網站風險評估及 PCI 規範遵循服務。";
$_LANG['store']['sitelock']['faqOneBodyLearnLinkText'] = "點此觀看「SiteLock 運作方式」影片";
$_LANG['store']['sitelock']['faqOneBodyLearnMore'] = "若要進一步瞭解 SiteLock，請參閱 :learnMoreLink";
$_LANG['store']['sitelock']['faqOneTitle'] = "什麼是 SiteLock？";
$_LANG['store']['sitelock']['faqSixBody'] = "SiteLock 信任標章是廣受認可的安全標章，可顯示在您的網站上。它能清楚表明網站安全且未受惡意軟體感染。若要新增標章，只要將 SiteLock 提供的程式碼片段加入網站頁尾即可。";
