$_LANG['store']['ssl']['dv']['descriptionContent'] = "<p>網域驗證憑證提供經濟實惠且快速的方式，讓您的網站啟用 SSL。此類憑證會驗證您擁有該網域，但不會進行其他組織層級的驗證。</p><p>網域驗證憑證適合個人網站、部落格、社群媒體，或任何不傳輸私人及機密資訊的網站。網域驗證憑證會啟用瀏覽器鎖頭圖示及 https，向網站訪客和客戶表明您重視他們的隱私。</p>";
