$_LANG['store']['ssl']['ev']['descriptionContent'] = "<p>EV SSL 是延伸驗證憑證，屬於目前等級最高的 SSL 憑證。相較於組織驗證或網域驗證 SSL 憑證，它能為您的網站帶來更高的可信度與信任。</p><p>在多數情況下，延伸驗證 SSL 會以綠色顯示您的公司或網站名稱。這種醒目的視覺驗證能讓訪客更有信心，確認網站與企業身分已經過查核，提升使用者對網站的信任與可信度；這也是多數大型公司及組織選擇 EV 憑證的原因。</p>";
