$_LANG['store']['ssl']['landingPage']['evs']['secureTitle'] = "使用萬用字元 SSL 保護整個網站";
$_LANG['store']['ssl']['landingPage']['evs']['webmailAccess'] = "網頁郵件（webmail.example.com）";
$_LANG['store']['ssl']['landingPage']['evs']['websiteControl'] = "控制台（mail.example.com）";
$_LANG['store']['ssl']['landingPage']['evs']['wildcardDescription'] = "萬用字元 SSL 憑證可保護您的主要網域及不限數量的子網域（例如 mail.example.com 或 ftp.example.com）。即使您沒有自行建立任何子網域，主機方案所含的功能也可能已使用數個子網域。";
$_LANG['store']['ssl']['landingPage']['evs']['wildcardSubtitle'] = "萬用字元 SSL 憑證能有效保護整個網站，確保使用者安全。";
$_LANG['store']['ssl']['landingPage']['faq']['a1'] = "SSL 憑證可在網際網路上加密資料，讓資料能在網頁伺服器與瀏覽器之間安全傳輸。使用 SSL 後，您的網站可採用 https 通訊協定，並在終端使用者的瀏覽器中顯示鎖頭圖示，表示連線安全。";
$_LANG['store']['ssl']['landingPage']['faq']['a2'] = "SSL 憑證是網際網路不可或缺的一環。它不只能加密您的電腦與網站所在伺服器之間的通訊，也能驗證網站是否如其所宣稱的身分。";
$_LANG['store']['ssl']['landingPage']['faq']['a3'] = "SSL 憑證有 3 種不同的驗證等級：網域驗證（DV）、組織驗證（OV）及延伸驗證（EV）。不同憑證類型的主要差異，在於憑證授權單位 RapidSSL、GeoTrust 與 DigiCert 核發憑證時要求並驗證的資訊。較高等級的憑證需要提供更多資訊，且通常會顯示在瀏覽器網址列中。例如，EV SSL 會將網址列顯示為綠色，並向訪客顯示組織名稱，以建立更高的信任度。";
$_LANG['store']['ssl']['landingPage']['faq']['a4'] = "萬用字元 SSL 憑證提供與其他 SSL 憑證相同的加密及驗證功能，也能套用至網站不限數量的子網域。萬用字元 SSL 憑證同時支援根網域（example.com）及其子網域。";
$_LANG['store']['ssl']['landingPage']['faq']['a5'] = "EV（延伸驗證）憑證是目前等級最高的 SSL 憑證，能為您的網站帶來最高程度的可信度與信任。EV 可確保消費者的個人及財務資訊受到最高等級的驗證保護。驗證項目還包括公司或機構的登記資料、申請者聯絡資訊，以及企業是否至少已營運 3 年。EV 憑證最適合用於攸關業務的重要網頁。";
$_LANG['store']['ssl']['landingPage']['faq']['a6'] = "您隨時可以改用我們的服務。我們提供極具競爭力的價格；如果您已有其他業者的 SSL 憑證，我們會將該憑證剩餘的有效期限加到您的新憑證，最多可延長 12 個月。";
