$_LANG['store']['ssl']['wildcard']['descriptionContent'] = "<p>萬用字元 SSL 可透過單一憑證保護不限數量的子網域。若您在相同網域上代管或管理多個網站或頁面，這是很好的解決方案。一次支付憑證費用，即可涵蓋您未來新增的子網域。</p><p>一般 SSL 憑證只會核發給單一完整網域名稱，例如 www.example.com，因此只能保護核發憑證時指定的網域。萬用字元 SSL 憑證則核發給 *.example.com，其中星號代表所有可能的子網域。</p><p>DV 和 OV SSL 憑證皆可選擇萬用字元方案。</p>";
