$_LANG['store']['threesixtymonitoring']['faq']['a1'] = "網站監控會測試網站的正常運作時間、效能與整體功能，確認網站正常運作並可供訪客瀏覽。透過網站監控結果，您可以在問題影響業務前先行排除。";
$_LANG['store']['threesixtymonitoring']['faq']['a10'] = "伺服器監控會定期掃描並追蹤伺服器的健康狀態，包括 CPU、載入時間、網路統計資料、記憶體、磁碟使用量等，協助您快速找出並解決問題。";
$_LANG['store']['threesixtymonitoring']['faq']['a11'] = "完整網站檢查可保護您的網路服務免於錯誤影響。系統會掃描整個網站或線上商店，找出失效連結、損毀圖片、JavaScript 錯誤及其他異常，協助避免網站問題。";
$_LANG['store']['threesixtymonitoring']['faq']['a2'] = "網站監控會依固定間隔測試您的網站（視方案而定，每 1、5 或 10 分鐘一次）。這些測試會偵測網站問題。發現問題時，360 Monitoring 會發出警示並記錄問題，供日後分析。";
$_LANG['store']['threesixtymonitoring']['faq']['a3'] = "效能監控工具與程序會監測 CPU 使用率、記憶體用量、磁碟使用量、輸入／輸出（I/O）效能及網路正常運作時間等系統資源，檢查系統運作狀況。360 Monitoring 會追蹤所有這些指標，確保系統順暢運作。";
$_LANG['store']['threesixtymonitoring']['faq']['a4'] = "效能監控對於在效能問題損害業務前及早發現問題至關重要。系統資源分析結果也能讓您主動規劃未來需求。";
$_LANG['store']['threesixtymonitoring']['faq']['a5'] = "透過 SSL 監控，您可以追蹤 SSL 憑證並預先規劃到期時間，確保憑證管理順暢無礙。";
$_LANG['store']['threesixtymonitoring']['faq']['a6'] = "您可從世界各地進行監控，監控據點包括澳洲、加拿大、芬蘭、法國、德國、日本、墨西哥、荷蘭、瑞典、英國及美國。";
