$_LANG['store']['weebly']['promo']['sidebar']['title'] = "強大的網站建置工具";
$_LANG['store']['xoviNow']['audience']['freelancersDesc'] = "XOVI NOW 專為個人網站與客戶網站提供即時效益，從初步網站健檢到改善搜尋引擎結果的建議，協助您逐步提升成效。";
$_LANG['store']['xoviNow']['audience']['freelancersTitle'] = "自由工作者";
$_LANG['store']['xoviNow']['audience']['smbizDesc'] = "不必是 SEO 專家，也能提升企業在 Google 的排名。XOVI NOW 會找出最適合您業務的關鍵字，同時掌握競爭對手的成效。";
$_LANG['store']['xoviNow']['audience']['smbizTitle'] = "中小型企業";
$_LANG['store']['xoviNow']['cartShortDescription'] = "使用精確、可靠且易於操作的網站排名、關鍵字與顧問工具，提升網站成效。";
$_LANG['store']['xoviNow']['cartTitle'] = "SEO 工具";
$_LANG['store']['xoviNow']['faq1'] = "什麼是 SEO？";
$_LANG['store']['xoviNow']['faq10'] = "什麼是專案能見度？";
$_LANG['store']['xoviNow']['faq10ans'] = "<p>您或許也曾想過：「等等，我不在乎那些與業務無關的關鍵字能見度。」您說得沒錯。能見度分數有助於了解整體成效並概略比較網站，但不會依您的特定關鍵字組合量身計算。</p><p>因此我們提供 <em>專案能見度</em>。這項指標的計算方式與能見度相同，但不採用跨產業的 500,000 個關鍵字，而是完全根據排名追蹤工具中的關鍵字計算。</p><p>換句話說，專案能見度是依據與您業務相關的專屬關鍵字組合計算的自訂能見度分數。</p><p>您可以在此找到專案能見度：<em>專案 → 排名追蹤工具 → 能見度</em>。</p><p>您也可以在排名追蹤工具中追蹤競爭對手的排名，並查看他們的專案能見度，讓比較更貼近實際情況。即使對方的產品或服務組合略有不同，專案能見度也只會計入雙方實際共用的關鍵字。</p>";
$_LANG['store']['xoviNow']['faq11'] = "能見度分數有什麼用途？";
$_LANG['store']['xoviNow']['faq11ans'] = "<p>您可以將能見度分數作為整體 SEO 成效、問題與最佳化潛力的指標。</p><p><strong>1. 了解整體 SEO 成效</strong></p><p>您可以追蹤個別關鍵字的排名，了解目前排名位置，這很重要。不過，排名追蹤無法讓您一覽排名整體的改善情況，能見度則可以。當 SEO 措施有效且排名提升時，能見度分數也會隨之提高。</p><p><strong>2. 診斷 SEO 問題</strong></p><p>能見度突然下降，表示 SEO 成效可能出現問題。請將能見度視為警示；若分數大幅下滑，應進一步查明原因。常見原因如下：</p><ul><li>您的網站受到 <strong>Google 懲罰</strong>。請查看 Search Console 通知，並遵循 <a href=\":googleWebmasterGuidelinesUrl\" target=\"_blank\">Google 搜尋基本要素</a>。</li><li>Google 演算法近期變更造成影響。請了解近期的 <strong>Google 更新</strong>及其影響。</li><li>競爭對手最佳化了網站與內容，現在排名超越您。請比較雙方過去與目前的<strong>能見度</strong>，並使用 <a href=\":waybackMachineUrl\" target=\"_blank\">Wayback Machine</a> 比較對方內容的變化。</li><li>您重新推出網站時沒有考量 SEO。例如，檢查 <em>robots.txt</em> 與 <em>.htaccess</em> 是否意外封鎖頁面、404 狀態碼是否增加、301 重新導向是否有誤，以及內部連結是否正常。<br><br>您變更了內容，但沒有改善排名；請考慮還原變更。<br><br>網站可能有技術問題。請執行<em>網站健檢</em>，或查看<strong><em>顧問工具</em></strong>中的待處理技術工作。也請在後台檢查可能造成問題的過時、近期更新或不相容<strong>外掛</strong>。<br><br>問題可能出在主機服務。請確認主機商近期是否變更設定、遭到入侵、搬遷伺服器或遇到技術問題，並檢查您的伺服器狀況。</li></ul><p>請注意，以上並未涵蓋所有可能原因；其中一項或多項可能同時發生，也可能另有其他原因。</p><p><strong>3. 比較競爭對手</strong></p><p>能見度是快速比較兩個以上網站的實用指標。將您的能見度與競爭對手比較，看看誰的表現較好、競爭對手過去是否曾超越您，以及誰在市場領先、您與最強勁對手的差距有多大。回答這些問題有助於制定 SEO 策略，讓您在所在領域取得並維持領先地位。</p><p><strong>4. 使用歷史資料追蹤能見度變化</strong></p><p>想了解網站長期以來的表現嗎？我們提供可回溯至 2009 年的歷史資料，不受季節性波動影響。您可以追蹤並比較過去的能見度，觀察長期變化。</p>";
$_LANG['store']['xoviNow']['faq12'] = "如何提升能見度分數？";
$_LANG['store']['xoviNow']['faq12ans'] = "<p>簡短回答：請勿將提升能見度列為 SEO 策略的目標。</p><p>詳細回答：能見度只是以單一指標<em>反映</em>您的排名品質，不會因此帶來更好的排名。請將目標設為提升相關關鍵字的排名，也就是潛在客戶實際用來尋找類似產品與服務的關鍵字。排名提升後，能見度也會提高；但真正重要的是排名。</p><p>一般來說，符合以下情況時，您的能見度分數會較高：</p><ul><li>網域中的 URL 排名良好</li><li>有許多已建立索引且排名良好的 URL</li><li>在搜尋量高的關鍵字上排名良好</li></ul>";
$_LANG['store']['xoviNow']['faq1ans'] = "<p>SEO 是 Search Engine Optimization（搜尋引擎最佳化）的縮寫，是一種重要的網路行銷策略，旨在將潛在客戶帶到您的網站。其目標是針對特定關鍵字最佳化網站，讓網站在搜尋引擎中取得較高排名。達成方式包括策略性地改善網站技術設定與內容，並從其他網域取得反向連結。</p><p>SEO 大致分為三類：</p><ol><li>關鍵字與排名</li><li>頁面內 SEO</li><li>頁面外 SEO</li></ol><p>SEO 專家會針對各類別採取措施，以符合搜尋引擎的排名因素。搜尋引擎會依據這些因素，決定網站在搜尋結果中的排名位置。</p>";
$_LANG['store']['xoviNow']['faq2'] = "為什麼需要 SEO？";
$_LANG['store']['xoviNow']['faq2ans'] = "<p>每天都有數百萬人使用搜尋引擎，尋找生活各方面的資訊或服務，例如食譜、指南、產品、航班、導航、票券、娛樂等。大多數人會透過搜尋引擎瀏覽網路，尋找問題的答案與解決方法。</p><p>一項研究指出，網路流量有 68% 來自搜尋引擎，其中 53% 來自自然搜尋，也就是非廣告（付費搜尋）的搜尋結果，而 SEO 有助於提升這類搜尋流量。</p><img src=\":image1\"><p>換句話說，自然搜尋（SEO）與付費搜尋（SEA，即搜尋結果中的廣告）占了網路流量的大部分。</p><p>搜尋引擎也深深影響我們的線下活動：我們會使用 Google、Apple 地圖與本地搜尋結果尋找地點及附近服務，例如美髮店、超市、餐廳和診所。我們會參考線上評論選擇目的地，也會透過搜尋引擎相關服務選擇開車、搭乘大眾運輸或步行前往。</p><p>試想您的企業、產品與服務都沒有出現在搜尋結果中，消費者在線上找不到您，無法購買產品，也找不到您的實體店面。他們很可能就會轉而選擇您的競爭對手。</p>";
$_LANG['store']['xoviNow']['faq3'] = "SEO 能為我帶來什麼？";
$_LANG['store']['xoviNow']['faq3ans'] = "<p>SEO 有助於使用者在線上找到您的企業、產品與服務，並進行購買。如前所述，人們也能更輕鬆地在線下找到您。</p><p>SEO 能提高重要關鍵字進入搜尋結果前段排名的機會。排名越高，就有越多人造訪您的網站，最好能出現在搜尋結果第一頁（或前十名）。</p><p><strong>為什麼要爭取首頁排名？</strong></p><p>問得好。研究顯示，31.7% 的使用者會點選第一個自然搜尋結果（排名第一）；高達 75.1% 的點擊都落在前三個搜尋結果。之後每往下一個排名，點擊數就會迅速減少。</p><img src=\":image2\"><p>這種行為顯示，使用者很少查看第二頁或更後面的結果，更不用說點選其中任何結果。</p><img src=\":image3\"><p>因此，企業至少要讓與業務相關的關鍵字出現在搜尋結果首頁。</p><p>簡而言之，自由工作者與企業主務必：</p><ol><li>擁有網站或任何形式的網路形象，即使產品或服務只在線下提供也一樣</li><li>執行 SEO，確保相關關鍵字排名在搜尋結果首頁</li></ol>";
$_LANG['store']['xoviNow']['faq4'] = "為什麼關鍵字很重要？";
$_LANG['store']['xoviNow']['faq4ans'] = "<p><em>關鍵字</em>是搜尋查詢（字詞、片語、句子與問題）的專業術語。使用者透過這些查詢尋找能回答問題、提供解決方法的內容。簡單來說，關鍵字是使用者與您網站之間的連結。搜尋引擎會比對關鍵字與網站，找出相關性最高的內容。</p><p>SEO 的重要工作之一，是找出能為網站帶來相關流量的關鍵字，也就是吸引潛在客戶。您需要找出人們搜尋類似產品或服務時會使用的搜尋字詞（即關鍵字），這個過程稱為關鍵字研究。理想情況下，關鍵字研究會整理出涵蓋整個客戶旅程中搜尋查詢的關鍵字清單。</p>";
$_LANG['store']['xoviNow']['faq5'] = "什麼是關鍵字最佳化？";
$_LANG['store']['xoviNow']['faq5ans'] = "<p>我們知道，相關性是取得搜尋結果高排名的重要因素。若要建立相關內容，請在個別子頁面或 URL 中，涵蓋某個關鍵字相關的主題與問題，並確保關鍵字出現在頁面上的重要位置。</p><p>假設您經營冰淇淋生意，其中一個關鍵字是 <em>s'mores ice cream sandwich</em>。接下來，您可以專注於所有與 <em>s'mores ice cream sandwich</em> 相關的內容。</p><p>您可以建立一道 <em>s'mores ice cream sandwich</em> 的食譜頁面，提供簡單易懂的食譜、圖片或影片，並回答使用者可能提出的問題。<em>S'mores ice cream sandwich</em> 是您的焦點關鍵字，應出現在頁面的 URL、標題、標頭等位置。</p><p>建立專屬且經過關鍵字最佳化的頁面，能讓搜尋引擎與使用者輕鬆了解頁面內容，進而讓頁面在相關搜尋結果中取得較佳排名。</p>";
$_LANG['store']['xoviNow']['faq6'] = "如何使用顧問工具";
$_LANG['store']['xoviNow']['faq6ans'] = "<p>首先，請點選頂端導覽列中的「顧問工具」，開啟顧問工具看板。這是 Kanban 看板，可依狀態整理工作。工作會依重要程度以不同顏色標示：</p><ul><li><strong>紅色：</strong>高。請儘速處理。</li><li><strong>黃色：</strong>中。請盡快處理。</li><li><strong>藍色：</strong>低。請留意，並在方便時處理。</li></ul><img src=\":image1\"><p>完成工作後，您可以拖放工作、依方案將工作指派給其他使用者，並依負責人篩選。</p><p>如前所述，工作包含一般 SEO 基本措施，以及每週自動執行網站健檢所發現的問題。</p>";
$_LANG['store']['xoviNow']['faq7'] = "如何取得其他網站的顧問工具？";
$_LANG['store']['xoviNow']['faq7ans'] = "<p>請注意，顧問工具功能需要有<em>專案</em>才能使用。此外，大多數顧問工具工作都是根據專案的網站量身設計，通常是您自己或客戶的網站。如果您管理多個網站，就需要為每個網站建立額外的專案。</p><p>若要新增或切換至其他專案，請點選頂端導覽列中的<em>專案</em>選單。依您的方案而定，新增專案前可能需要先升級方案。</p>";
$_LANG['store']['xoviNow']['faq8'] = "如何將工作指派給其他使用者？";
$_LANG['store']['xoviNow']['faq8ans'] = "<p>若要將工作指派給其他使用者，您需要支援額外使用者的方案。如果方案包含額外使用者，顧問工具與工作中就會顯示「負責人」選單。選擇使用者即可指派工作，也可以依負責人篩選顧問工具。若要新增使用者，請點選個人檔案頭像，再選擇<em>使用者</em>。若您的方案不包含額外使用者，顧問工具或工作中就不會顯示<em>負責人</em>選單。請升級方案以新增使用者。</p>";
$_LANG['store']['xoviNow']['faq9'] = "已處理過的工作為什麼又出現？";
$_LANG['store']['xoviNow']['faq9ans'] = "<p>您可能會再次看到已解決或處理過的工作，原因有兩個。如前所述，工作包含 SEO 基本措施，以及每週自動執行網站健檢所發現的問題。</p><p>首先，SEO 基本措施工作對所有人都相同，不會依您的網站或業務量身設計。例如，我們不知道您是否已為企業建立 Google 帳戶並設定 Search Console，或是否已安裝 SEO 外掛。如果您已完成這些工作，做得好！只要將工作標示為「已完成」即可。</p><p>第二，顧問工具會根據每週自動網站健檢的結果更新。也就是說，如果網站健檢發現與先前已完成工作相關的問題，該工作會自動更新，並重新出現在「未處理」區段。</p>";
